-- Origin SQL:
SELECT id FROM t ORDER BY ts LIMIT 10 WITH TIES;
SELECT id FROM t ORDER BY ts LIMIT 5, 10 WITH TIES;
SELECT id FROM t ORDER BY ts LIMIT 1 BY id LIMIT 10 WITH TIES;
SELECT id FROM (SELECT id, ts FROM t ORDER BY ts LIMIT 10 WITH TIES) GROUP BY id


-- Format SQL:
SELECT id FROM t ORDER BY ts LIMIT 10 WITH TIES;
SELECT id FROM t ORDER BY ts LIMIT 5, 10 WITH TIES;
SELECT id FROM t ORDER BY ts LIMIT 1 BY id LIMIT 10 WITH TIES;
SELECT id FROM (SELECT id, ts FROM t ORDER BY ts LIMIT 10 WITH TIES) GROUP BY id;
